-module(xls_frame_layout).
-moduledoc "Renders frame configuration and capacity checks from hls_frame_layout. Called by artifact writers; deployed codecs depend only on the runtime layout.".
%% Canonical frame support rendering.
-export([config/1, assert/1]).

-doc "Emits the complete per-build frame_config DSLX module from the canonical typed header schema and selected payload capacity.".
-spec config(hls_frame_layout:layout()) -> iodata().
config(Layout) ->
    Header = hls_field_layout:layout(hls_frame_layout:header_fields(), lsb),
    [
        "// Generated by xls_frame_layout:config/1.\n",
        "// Ordinary actor capacity; independent bridge/debug formats retain their own bounds.\n"
        "\n",
        "pub const PAYLOAD_WORDS = u32:",
        integer_to_list(hls_frame_layout:payload_words(Layout)),
        ";\n",
        "pub const WORD_BITS = u32:",
        integer_to_list(hls_frame_layout:word_bits()),
        ";\n",
        "pub const HEADER_BITS = u32:",
        integer_to_list(hls_frame_layout:header_bits()),
        ";\n",
        "pub const PAYLOAD_BITS = PAYLOAD_WORDS * WORD_BITS;\n",
        "pub const FRAME_BITS = HEADER_BITS + PAYLOAD_BITS;\n"
        "\n",
        "// Canonical header in ascending numeric byte order.\n",
        xls_struct_codec:declaration("Header", Header),
        "\n",
        "// Decodes the complete canonical header word.\n",
        xls_struct_codec:decoder("Header", "header_from_bits", Header),
        "\n",
        "// Encodes fields without changing their numeric byte positions.\n",
        xls_struct_codec:encoder("Header", "bits_from_header", Header)
    ].

-doc "Emits a module-level check that the imported axis support matches the artifact's selected layout.".
-spec assert(hls_frame_layout:layout()) -> iodata().
assert(Layout) ->
    [
        "const_assert!(axis::FRAME_BITS == u32:",
        integer_to_list(hls_frame_layout:frame_bits(Layout)),
        ");\n"
        "\n"
    ].
